class Solution {
  private long[] bit;
  private int n;

  private void rangeAdd(int l, int r, long d) {
    add(l, d);
    add(r + 1, -d);
  }

  private void add(int i, long d) {
    for (; i <= n + 1; i += i & -i) bit[i] += d;
  }

  private long point(int i) {
    long s = 0;
    for (; i > 0; i -= i & -i) s += bit[i];
    return s;
  }

  public int[] treeQueries(int n, int[][] edges, int[][] queries) {
    this.n = n;
    bit = new long[n + 3];
    int[] start = new int[n + 2];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 1; i <= n + 1; i++) start[i] += start[i - 1];
    int[] fill = new int[n + 1], to = new int[2 * (n - 1)], w = new int[2 * (n - 1)];
    for (int[] e : edges) {
      int p = start[e[0]] + fill[e[0]]++;
      to[p] = e[1];
      w[p] = e[2];
      p = start[e[1]] + fill[e[1]]++;
      to[p] = e[0];
      w[p] = e[2];
    }
    int[] tin = new int[n + 1], tout = new int[n + 1], par = new int[n + 1], wt = new int[n + 1];
    int[] stack = new int[n + 1], ptr = new int[n + 1];
    int sp = 0, timer = 0;
    stack[sp++] = 1;
    tin[1] = ++timer;
    for (int i = 1; i <= n; i++) ptr[i] = start[i];
    while (sp > 0) {
      int u = stack[sp - 1];
      if (ptr[u] < start[u + 1]) {
        int p = ptr[u]++;
        int v = to[p];
        if (v == par[u]) continue;
        par[v] = u;
        wt[v] = w[p];
        tin[v] = ++timer;
        stack[sp++] = v;
      } else {
        tout[u] = timer;
        sp--;
      }
    }
    for (int v = 2; v <= n; v++) rangeAdd(tin[v], tout[v], wt[v]);
    int cnt = 0;
    for (int[] q : queries) if (q[0] == 2) cnt++;
    int[] ans = new int[cnt];
    int idx = 0;
    for (int[] q : queries) {
      if (q[0] == 1) {
        int c = par[q[1]] == q[2] ? q[1] : q[2];
        rangeAdd(tin[c], tout[c], q[3] - wt[c]);
        wt[c] = q[3];
      } else {
        ans[idx++] = (int) point(tin[q[1]]);
      }
    }
    return ans;
  }
}
